/* merian-metamorphosis — scroll is time: engraving line first, then
   hand-colour washes flood in wet-on-wet. Final frame is the plate itself. */
export function merianMetamorphosis(runway, opts = {}) {
  const frame = runway.querySelector('.mm-frame');
  const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
  let raf = 0, target = 0, current = reduced ? 1 : 0, visible = true, destroyed = false;
  const clamp01 = v => Math.min(1, Math.max(0, v));
  function measure() {
    const r = runway.getBoundingClientRect();
    const total = runway.offsetHeight - innerHeight;
    target = total > 0 ? clamp01(-r.top / total) : 1;
  }
  function apply() {
    frame.style.setProperty('--p', current.toFixed(4));
    frame.style.setProperty('--wet', (4 * current * (1 - current)).toFixed(4));
  }
  let vel = 0;
  function tick() {
    raf = 0;
    const w = target > current ? 10 : 15;
    const dt = 1 / 60;
    vel += (-w * w * (current - target) - 2 * w * vel) * dt;
    current = clamp01(current + vel * dt);
    if (Math.abs(target - current) < 0.0004 && Math.abs(vel) < 0.0004) { current = target; vel = 0; apply(); return; }
    apply();
    if (visible && !document.hidden && !destroyed) raf = requestAnimationFrame(tick);
  }
  function kick() { measure(); if (!raf && visible && !destroyed) raf = requestAnimationFrame(tick); }
  const onScroll = () => kick(), onResize = () => kick();
  addEventListener('scroll', onScroll, { passive: true });
  addEventListener('resize', onResize);
  const io = new IntersectionObserver(e => { visible = e[0].isIntersecting; if (visible) kick(); else if (raf) { cancelAnimationFrame(raf); raf = 0; } });
  io.observe(runway);
  if (reduced) { current = target = 1; apply(); }
  else kick();
  return function destroy() {
    destroyed = true;
    if (raf) cancelAnimationFrame(raf);
    removeEventListener('scroll', onScroll); removeEventListener('resize', onResize);
    io.disconnect();
    frame.style.removeProperty('--p'); frame.style.removeProperty('--wet');
  };
}
let api = null;
const el = document.querySelector('[data-merian-metamorphosis]');
if (el) api = merianMetamorphosis(el);
export function destroy() { if (api) { api(); api = null; } }
if (typeof window !== 'undefined') window.__merianMetamorphosis = { destroy };

/* merian-metamorphosis — hand-colour washes flood a Merian engraving. */
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{background:#f3efe4;overflow-x:hidden}
.mm-runway{height:360vh;position:relative}
.mm-stage{position:sticky;top:0;height:100svh;display:grid;place-items:center;background:#f3efe4;overflow:hidden}
.mm-frame{position:relative;height:min(94svh,1180px);aspect-ratio:1920/2512;max-width:94vw;touch-action:pan-y}
.mm-frame img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;display:block;pointer-events:none;user-select:none;-webkit-user-drag:none}
.mm-base{filter:grayscale(1) contrast(1.14) brightness(1.07) sepia(.18)}
.mm-wash{filter:saturate(1.18) brightness(1.03);opacity:.55;
  -webkit-mask-image:radial-gradient(circle at 62% 30%,#000 calc(var(--p,0)*95%),transparent calc(var(--p,0)*95% + 14%));
  mask-image:radial-gradient(circle at 62% 30%,#000 calc(var(--p,0)*95%),transparent calc(var(--p,0)*95% + 14%))}
.mm-top{
  -webkit-mask-image:radial-gradient(circle at 38% 58%,#000 calc(var(--p,0)*135%),transparent calc(var(--p,0)*135% + 13%));
  mask-image:radial-gradient(circle at 38% 58%,#000 calc(var(--p,0)*135%),transparent calc(var(--p,0)*135% + 13%))}
.mm-sheen{position:absolute;inset:0;pointer-events:none;mix-blend-mode:soft-light;opacity:var(--wet,0);
  background:radial-gradient(60% 45% at 40% 55%,rgba(255,252,235,.95),rgba(255,252,235,0) 70%)}
@media (prefers-reduced-motion: reduce){
  .mm-runway{height:auto}
  .mm-stage{position:static;height:auto;padding:4svh 0}
  .mm-top,.mm-wash{-webkit-mask-image:none;mask-image:none}
  .mm-wash{opacity:0}.mm-sheen{opacity:0}
}

